use moloch_replay::{engine::Engine,session::Session};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
fn iso(n:i64)->String{chrono::DateTime::from_timestamp_millis(1_792_022_400_000+n).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn policy()->Value{json!({"initialCash":"100.000000","maximumCommitted":"40.000000","maximumMarketCost":"10.000000","quantity":15,"maximumMarkets":3,"minimumSpreadTicks":1000,"entryStopAt":iso(100000)})}
fn book(ex:&str)->Value{json!({"type":"book","receivedAt":iso(0),"book":{"tournamentId":"cup","marketId":ex,"exchangeId":ex,"sequence":"1","sourceAt":iso(0),"requestStartedAt":iso(0),"receivedAt":iso(0),"bids":[{"price":"0.400000","quantity":20}],"asks":[{"price":"0.450000","quantity":20}]}})}
fn engine_with(p:&Value)->Engine{let mut e=Engine::new_live(p).unwrap();for ex in ["101","102","103"]{e.advance(&book(ex)).unwrap();}assert!(e.order_records().is_empty());e}
fn engine()->Engine{engine_with(&policy())}
fn reserve(n:usize)->Value{json!({"type":"live_package_reserve","source":"moloch_live_dispatcher","receivedAt":iso(1),"processedAt":iso(1),"packageId":"package-1","proofHash":"a".repeat(64),"bankScope":{"runId":"run-1","bankManifestHash":"b".repeat(64),"tournamentId":"cup"},"expiresAt":iso(9000),"economics":{"maximumCost":if n==2{"4.500000"}else{"6.750000"},"minimumPayout":if n==2{"5.000000"}else{"7.500000"},"minimumSurplus":if n==2{"0.500000"}else{"0.750000"},"feeTotal":"0.000000"},"legs":(["101","102","103"].into_iter().take(n).map(|ex|json!({"marketId":ex,"exchangeId":ex,"side":"YES","quantity":5,"limitPrice":"0.450000","bookHash":hash(&book(ex)["book"])})).collect::<Vec<_>>())})}
fn event(kind:&str,at:i64)->Value{let r=reserve(2);json!({"type":kind,"source":"moloch_live_dispatcher","receivedAt":iso(at),"processedAt":iso(at),"packageId":r["packageId"],"proofHash":r["proofHash"],"bankScope":r["bankScope"],"requestHash":"c".repeat(64),"idempotencyKey":"run-package-1","bookHashes":{"101":hash(&book("101")["book"]),"102":hash(&book("102")["book"]) }})}
fn attempted()->Engine{let mut e=engine();e.advance(&reserve(2)).unwrap();e.advance(&event("live_package_attempt",3001)).unwrap();e}
fn actual(kind:&str,q:&Value,at:i64)->Value{json!({"type":kind,"source":"official_sig_api_v1","receiptHash":"d".repeat(64),"orderId":q["id"],"actualOrderId":format!("9{}",q["id"].as_u64().unwrap()),"exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":q["action"],"quantity":q["quantity"],"price":q["price"],"receivedAt":iso(at)})}
fn fill(q:&Value,n:u64,at:i64)->Value{let mut f=actual("actual_fill",q,at);f["fillId"]=json!(format!("8{}{}",q["id"].as_u64().unwrap(),at));f["quantity"]=json!(n);f["fee"]=json!("0.000000");f["executedAt"]=json!(iso(at));f}
fn terminal(q:&Value,n:u64,at:i64)->Value{let mut f=actual("actual_order_terminal",q,at);f["filledQuantity"]=json!(n);f["fillsComplete"]=json!(true);f["status"]=json!(if n==5{"filled"}else{"canceled"});f}
fn deny(e:&mut Engine,v:&Value){let before=e.report().unwrap();let orders=e.order_records();assert!(e.advance(v).is_err(),"accepted {v}");assert_eq!(e.report().unwrap(),before);assert_eq!(e.order_records(),orders);}
#[test]fn full_funding_two_and_three_leg_reservation_is_exact(){for n in [2,3]{let mut e=engine();assert!(e.report().unwrap().get("livePackages").is_none());e.advance(&reserve(n)).unwrap();assert_eq!(e.order_records().len(),n);assert_eq!(e.report().unwrap()["reservedCash"],if n==2{"4.500000"}else{"6.750000"});assert!(e.package_blocks_submissions());for q in e.order_records(){assert!(e.is_package_order(q["id"].as_u64().unwrap()));}assert_eq!(e.package_records()[0]["phase"],"reserved");}}
#[test]fn failed_final_leg_funding_rolls_back_all_native_orders_and_cash(){for key in ["maximumCommitted","initialCash"]{let mut p=policy();p[key]=json!("4.000000");if key=="initialCash"{p["maximumCommitted"]=json!("4.000000");}let mut e=engine_with(&p);deny(&mut e,&reserve(2));assert_eq!(e.report().unwrap()["reservedCash"],"0.000000");assert!(!e.package_blocks_submissions());}}
#[test]fn zero_fees_caps_entry_allowlist_and_exact_economics_required(){for case in ["fee","cap","quantity","markets","disabled","allowlist","economics"]{let mut p=policy();match case{"fee"=>p["feeBps"]=json!(1),"cap"=>p["maximumMarketCost"]=json!("2.000000"),"quantity"=>p["quantity"]=json!(4),"markets"=>p["maximumMarkets"]=json!(1),"disabled"=>p["entriesEnabled"]=json!(false),"allowlist"=>p["entryExchangeIds"]=json!(["101"]),_=>()};let mut e=engine_with(&p);let mut r=reserve(2);if case=="economics"{r["economics"]["maximumCost"]=json!("4.400000");}deny(&mut e,&r);}}
#[test]fn stale_hash_depth_scope_duplicate_exchanges_and_expiry_deny(){for case in ["hash","depth","scope","duplicate","expired","late","paststop"]{let mut e=engine();let mut r=reserve(2);match case{"hash"=>r["legs"][0]["bookHash"]=json!("f".repeat(64)),"depth"=>{r["legs"][0]["limitPrice"]=json!("0.440000");},"scope"=>r["bankScope"]["tournamentId"]=json!("other"),"duplicate"=>r["legs"][1]=r["legs"][0].clone(),"expired"=>r["expiresAt"]=json!(iso(3001)),"late"=>{r["receivedAt"]=json!(iso(11000));r["processedAt"]=json!(iso(11000));r["expiresAt"]=json!(iso(18000));},_=>r["expiresAt"]=json!(iso(100001))};deny(&mut e,&r);}}
#[test]fn permanent_id_and_unresolved_package_fences(){let mut e=engine();e.advance(&reserve(2)).unwrap();deny(&mut e,&reserve(2));let mut r=reserve(2);r["packageId"]=json!("package-2");deny(&mut e,&r);}
#[test]fn ordinary_tick_coverage_and_retirement_cannot_release_package(){let mut e=engine();e.advance(&reserve(2)).unwrap();let q=e.order_records()[0].clone();let mut r=actual("unsubmitted_intent_retired",&q,2);r["source"]=json!("moloch_live_dispatcher");r["confirmedNetworkAttempts"]=json!(0);deny(&mut e,&r);e.advance(&json!({"type":"tick","receivedAt":iso(20000)})).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"4.500000");assert!(e.order_records().iter().all(|q|q["retired"]==false&&q["cancelEffectiveAt"].is_null()));assert!(e.fills().is_empty());}
#[test]fn never_attempted_package_can_release_only_with_exact_zero_proof(){let mut e=engine();e.advance(&reserve(2)).unwrap();let mut v=event("live_package_no_execution",2);v["evidence"]=json!({"kind":"never_attempted","confirmedNetworkAttempts":1});deny(&mut e,&v);v["evidence"]["confirmedNetworkAttempts"]=json!(0);e.advance(&v).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"0.000000");assert!(!e.package_blocks_submissions());let mut reused=reserve(2);reused["receivedAt"]=json!(iso(3));reused["processedAt"]=json!(iso(3));deny(&mut e,&reused);}
#[test]fn attempt_is_once_original_window_and_changed_book_deny(){let mut e=engine();e.advance(&reserve(2)).unwrap();deny(&mut e,&event("live_package_attempt",3000));e.advance(&event("live_package_attempt",3001)).unwrap();deny(&mut e,&event("live_package_attempt",3002));let mut n=event("live_package_no_execution",3002);n["evidence"]=json!({"kind":"never_attempted","confirmedNetworkAttempts":0});deny(&mut e,&n);let mut e=engine();e.advance(&reserve(2)).unwrap();deny(&mut e,&event("live_package_attempt",9000));let mut b=book("101");b["receivedAt"]=json!(iso(3001));for k in ["receivedAt","sourceAt","requestStartedAt"]{b["book"][k]=json!(iso(3001));}b["book"]["sequence"]=json!("2");e.advance(&b).unwrap();deny(&mut e,&event("live_package_attempt",3001));let mut attempt=event("live_package_attempt",3001);attempt["bookHashes"]["101"]=json!(hash(&b["book"]));e.advance(&attempt).unwrap();}
fn zero(status:u64,code:&str)->Value{let mut z=event("live_package_no_execution",3002);let response=json!({"error":{"code":code,"message":"sanitized"}});z["evidence"]=json!({"kind":"official_multi_leg_zero_execution","completeBody":true,"requestHash":"c".repeat(64),"receiptHash":"e".repeat(64),"responseHash":hash(&response),"response":response,"status":status,"requestStartedAt":iso(3001),"receivedAt":iso(3002)});z}
#[test]fn attempted_zero_requires_allowlisted_complete_bound_response(){let mut e=attempted();for(status,code)in [(500,"INTERNAL"),(409,"CONFLICT"),(200,"RATE_LIMITED")]{deny(&mut e,&zero(status,code));}let mut v=zero(429,"RATE_LIMITED");v["evidence"]["responseHash"]=json!("f".repeat(64));deny(&mut e,&v);v=zero(429,"RATE_LIMITED");v["evidence"]["completeBody"]=json!(false);deny(&mut e,&v);e.advance(&zero(429,"RATE_LIMITED")).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"0.000000");}
#[test]fn unknown_retains_every_reservation_and_blocks_new_submissions(){let mut e=attempted();e.advance(&event("live_package_unknown",3002)).unwrap();assert_eq!(e.package_records()[0]["phase"],"unknown");e.advance(&json!({"type":"tick","receivedAt":iso(20000)})).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"4.500000");assert!(e.package_blocks_submissions());}
#[test]fn acknowledgments_never_create_positions_and_wrapper_is_transactional(){let mut e=attempted();let qs=e.order_records();let mut v=event("live_package_ack",3002);let mut bad=actual("actual_order_ack",&qs[1],3002);bad["quantity"]=json!(4);v["acknowledgments"]=json!([actual("actual_order_ack",&qs[0],3002),bad]);deny(&mut e,&v);assert!(e.live_order_bindings().is_empty());v["acknowledgments"][1]=actual("actual_order_ack",&qs[1],3002);e.advance(&v).unwrap();assert_eq!(e.package_records()[0]["phase"],"acknowledged");assert_eq!(e.report().unwrap()["ownedCost"],"0.000000");assert!(e.fills().is_empty());deny(&mut e,&zero(429,"RATE_LIMITED"));}
#[test]fn actual_partial_fill_and_terminal_release_only_remaining_leg_funding(){let mut e=attempted();let qs=e.order_records();for q in &qs{e.advance(&actual("actual_order_ack",q,3002)).unwrap();}e.advance(&fill(&qs[0],2,3003)).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"3.600000");assert_eq!(e.report().unwrap()["ownedCost"],"0.900000");e.advance(&terminal(&qs[0],2,3004)).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"2.250000");deny(&mut e,&event("live_package_complete",3005));assert!(e.package_blocks_submissions());assert_eq!(e.fills().len(),1);}
#[test]fn complete_requires_real_full_fills_and_terminal_then_holds_portfolio_protected(){let mut e=attempted();let qs=e.order_records();for q in &qs{e.advance(&actual("actual_order_ack",q,3002)).unwrap();}for q in &qs{e.advance(&fill(q,5,3003)).unwrap();}deny(&mut e,&event("live_package_complete",3004));for q in &qs{e.advance(&terminal(q,5,3004)).unwrap();}e.advance(&event("live_package_complete",3005)).unwrap();assert!(!e.package_blocks_submissions());assert_eq!(e.package_records()[0]["phase"],"complete");assert_eq!(e.report().unwrap()["ownedCost"],"4.500000");let mut p=e.policy().clone();p["maximumInventoryAgeMs"]=json!(1);e.update_policy(&p).unwrap();e.advance(&json!({"type":"tick","receivedAt":iso(20000)})).unwrap();assert_eq!(e.order_records().len(),2);assert!(e.order_records().iter().all(|q|q["action"]=="buy"));}
#[test]fn package_books_are_readonly_noninvalid_current_raw_snapshots(){let mut e=engine();let books=e.live_package_books();assert_eq!(books.len(),3);assert!(books.contains(&book("101")["book"]));e.advance(&json!({"type":"gap","exchangeId":"101","marketId":"101","tournamentId":"cup","receivedAt":iso(1)})).unwrap();assert_eq!(e.live_package_books().len(),2);}
#[test]fn unsupported_seed_cannot_drop_package_state(){assert!(Engine::from_seed_state(&json!({"livePackages":[]})).is_err());}
#[test]fn durable_session_restart_replays_reservation_attempt_and_unknown_exactly(){let root=std::env::temp_dir().join(format!("moloch-package-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));let seed=json!({"runId":"run-1","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let expected;let orders;{let mut s=Session::open_live(&root,&policy(),&seed).unwrap();for(i,ex)in ["101","102","103"].into_iter().enumerate(){s.accept("books",i as u64+1,&book(ex)).unwrap();}s.accept("dispatch",1,&reserve(2)).unwrap();s.accept("dispatch",2,&event("live_package_attempt",3001)).unwrap();s.accept("dispatch",3,&event("live_package_unknown",3002)).unwrap();expected=s.engine().report().unwrap();orders=s.engine().order_records();}{let s=Session::open_live(&root,&policy(),&seed).unwrap();assert_eq!(s.engine().report().unwrap(),expected);assert_eq!(s.engine().order_records(),orders);assert!(s.engine().package_blocks_submissions());}std::fs::remove_dir_all(root).unwrap();}

#[test]fn zero_execution_receipt_cannot_predate_the_attempt(){let mut e=attempted();let mut z=zero(429,"RATE_LIMITED");z["evidence"]["requestStartedAt"]=json!(iso(1000));deny(&mut e,&z);}
#[test]fn current_worse_or_insufficient_book_cannot_attempt_frozen_economics(){for case in ["worse","depth","gap"]{let mut e=engine();e.advance(&reserve(2)).unwrap();let mut b=book("101");b["receivedAt"]=json!(iso(3001));for k in ["receivedAt","sourceAt","requestStartedAt"]{b["book"][k]=json!(iso(3001));}b["book"]["sequence"]=json!("2");match case{"worse"=>b["book"]["asks"][0]["price"]=json!("0.460000"),"depth"=>b["book"]["asks"][0]["quantity"]=json!(4),_=>b["book"]["invalid"]=json!(true)};e.advance(&b).unwrap();let mut a=event("live_package_attempt",3001);a["bookHashes"]["101"]=json!(hash(&b["book"]));deny(&mut e,&a);assert_eq!(e.report().unwrap()["reservedCash"],"4.500000");}}
#[test]fn no_side_uses_complementary_bid_depth_at_full_wire_limit(){let mut e=engine();let mut r=reserve(2);r["legs"][0]["side"]=json!("NO");r["legs"][0]["limitPrice"]=json!("0.600000");r["economics"]=json!({"maximumCost":"5.250000","minimumPayout":"6.000000","minimumSurplus":"0.750000","feeTotal":"0.000000"});e.advance(&r).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"5.250000");}
#[test]fn aggregate_quantity_cap_applies_to_all_package_legs_together(){let mut p=policy();p["quantity"]=json!(9);let mut e=engine_with(&p);deny(&mut e,&reserve(2));}
#[test]fn native_local_not_sent_never_accepts_absence_or_unknown_phase(){let mut e=attempted();let mut v=event("live_package_no_execution",3002);v["evidence"]=json!({"kind":"local_queue_not_sent_v1","requestHash":"c".repeat(64),"sdkError":{"code":"AUTHORITY_REJECTED","status":null,"orderId":null,"apiCode":null,"mayHaveExecuted":false},"queueProof":{"tailRecord":{"state":{"unknown":{},"active":null,"manual_review":false}}}});deny(&mut e,&v);e.advance(&event("live_package_unknown",3002)).unwrap();deny(&mut e,&v);assert_eq!(e.report().unwrap()["reservedCash"],"4.500000");assert!(e.fills().is_empty());}

// Replay fixtures intentionally contain no account/client. Runtime tests must
// separately prove this evidence comes from the original locked dispatch log.
fn never_dispatch_fixture()->(Engine,Value){
 let mut e=engine();let mut r=reserve(2);let semantic=json!({"fixture":"native replay witness","wireLegs":r["legs"]});r["proofHash"]=json!(hash(&semantic));
 let scope=json!({"tournamentId":"cup","tournamentSlug":"cup","exchanges":{"101":"101","102":"102"}});
 let body=json!({"executionMode":"allOrNone","idempotencyKey":"run-package-1","legs":[{"exchangeId":"101","side":"yes","action":"buy","quantity":5,"price":0.45,"tournamentId":"cup"},{"exchangeId":"102","side":"yes","action":"buy","quantity":5,"price":0.45,"tournamentId":"cup"}]});
 let text=format!("{{\"method\":\"POST\",\"endpoint\":\"/orders/multi-leg\",\"body\":{body},\"bodyJson\":null}}");let spec:Value=serde_json::from_str(&text).unwrap();let request=format!("{:x}",Sha256::digest(text.as_bytes()));
 e.advance(&r).unwrap();let mut a=r.clone();a["type"]=json!("live_package_attempt");a["receivedAt"]=json!(iso(3001));a["processedAt"]=json!(iso(3001));a["requestHash"]=json!(request);a["idempotencyKey"]=json!("run-package-1");a["bookHashes"]=json!({"101":hash(&book("101")["book"]),"102":hash(&book("102")["book"])});e.advance(&a).unwrap();
 let admission=json!({"proof":semantic,"reserve":r,"spec":spec,"request_hash":request,"scope":scope,"permit":{"runId":"run-1","intentId":"package-1"},"basket":{"idempotencyKey":"run-package-1"},"queue_scope":"original-account","queue_binding":{"intent":"run-1:package-1","key":"run-package-1","payload_hash":hash(&json!({"scope":scope,"spec":spec}))}});
 let fence=json!({"kind":"never_attempted","packageId":"package-1","at":iso(3002),"requestHash":request,"admissionHash":hash(&admission),"priorHead":{"sequence":1,"hash":"d".repeat(64)}});
 let mut row=json!({"schemaVersion":1,"sequence":2,"previous":"d".repeat(64),"event":fence});row["hash"]=json!(hash(&row));
 let record=json!({"admission":admission,"phase":"never_attempted","attemptedAt":null,"outcome":fence});
 let mut v=r;v["type"]=json!("live_package_no_execution");v["receivedAt"]=json!(iso(3002));v["processedAt"]=json!(iso(3003));v["evidence"]=json!({"kind":"dispatch_never_attempted_v1","requestHash":request,"requestJson":text,"dispatchRecordHash":hash(&record),"dispatchRecord":record,"dispatchFenceRow":row,"dispatchHead":{"sequence":2,"hash":row["hash"],"poisoned":false},"journalBytes":1234,"journalSha256":"e".repeat(64),"journalLastClockMs":1_792_022_403_002i64});(e,v)
}
#[test]fn never_physical_dispatch_fence_releases_only_reservation_without_profit_or_fill(){let(mut e,v)=never_dispatch_fixture();let cash=e.report().unwrap()["cash"].clone();e.advance(&v).unwrap();assert_eq!(e.report().unwrap()["cash"],cash);assert_eq!(e.report().unwrap()["realized"],"0.000000");assert_eq!(e.report().unwrap()["reservedCash"],"0.000000");assert_eq!(e.package_records()[0]["phase"],"no_execution");assert!(e.live_order_bindings().is_empty()&&e.fills().is_empty());deny(&mut e,&v);}
#[test]fn never_dispatch_rejects_missing_changed_or_inconsistent_fence_source(){let(e,v)=never_dispatch_fixture();for case in ["phase","attempted","request","admission","fence","head","clock","source","extra"]{let mut bad=v.clone();match case{"phase"=>bad["evidence"]["dispatchRecord"]["phase"]=json!("intent"),"attempted"=>bad["evidence"]["dispatchRecord"]["attemptedAt"]=json!(iso(3001)),"request"=>bad["evidence"]["requestJson"]=json!("{}"),"admission"=>bad["evidence"]["dispatchRecord"]["admission"]["reserve"]["bankScope"]["runId"]=json!("another"),"fence"=>bad["evidence"]["dispatchFenceRow"]["event"]["kind"]=json!("attempt"),"head"=>bad["evidence"]["dispatchHead"]["sequence"]=json!(1),"clock"=>bad["evidence"]["journalLastClockMs"]=json!(1_792_022_403_004i64),"source"=>bad["evidence"]["journalSha256"]=Value::Null,_=>bad["evidence"]["queueAbsence"]=json!(true)}let mut candidate=e.clone();deny(&mut candidate,&bad);}}
#[test]fn never_dispatch_unknown_ack_and_partial_fill_never_release(){let(e,v)=never_dispatch_fixture();for case in ["unknown","ack","fill"]{let mut candidate=e.clone();if case=="unknown"{let mut u=v.clone();u["type"]=json!("live_package_unknown");u["requestHash"]=v["evidence"]["requestHash"].clone();u["receivedAt"]=json!(iso(3002));u["processedAt"]=json!(iso(3002));candidate.advance(&u).unwrap();}else{let q=candidate.order_records()[0].clone();candidate.advance(&actual("actual_order_ack",&q,3002)).unwrap();if case=="fill"{candidate.advance(&fill(&q,1,3002)).unwrap();}}let before=candidate.report().unwrap()["reservedCash"].clone();deny(&mut candidate,&v);assert_eq!(candidate.report().unwrap()["reservedCash"],before);}}
#[test]fn typed_dispatch_witness_is_not_a_reserved_or_absence_alias(){let(_,v)=never_dispatch_fixture();let r=v["evidence"]["dispatchRecord"]["admission"]["reserve"].clone();let mut e=engine();e.advance(&r).unwrap();deny(&mut e,&v);let(mut e,mut v)=never_dispatch_fixture();v["evidence"]=json!({"kind":"dispatch_never_attempted_v1","confirmedNetworkAttempts":0,"queueEmpty":true});deny(&mut e,&v);}

#[test]fn thirty_second_intent_does_not_turn_ten_second_books_into_fresh_attempt_facts(){
 let mut e=engine();let mut r=reserve(2);r["expiresAt"]=json!(iso(30001));e.advance(&r).unwrap();assert_eq!(e.package_records()[0]["expiresAt"],1_792_022_430_001i64);
 let mut a=event("live_package_attempt",15000);deny(&mut e,&a);
 for ex in ["101","102"]{let mut b=book(ex);b["receivedAt"]=json!(iso(15000));for k in ["receivedAt","sourceAt","requestStartedAt"]{b["book"][k]=json!(iso(15000));}b["book"]["sequence"]=json!("2");a["bookHashes"][ex]=json!(hash(&b["book"]));e.advance(&b).unwrap();}
 e.advance(&a).unwrap();assert_eq!(e.package_records()[0]["phase"],"attempted");assert_eq!(e.package_records()[0]["expiresAt"],1_792_022_430_001i64);assert_eq!(e.report().unwrap()["reservedCash"],"4.500000");assert!(e.fills().is_empty());
}
#[test]fn thirty_second_expiry_does_not_relax_stale_reservation_books_or_source_clocks(){
 for case in ["all_old","source_old","request_old"]{let mut e=engine();let mut r=reserve(2);r["receivedAt"]=json!(iso(15000));r["processedAt"]=json!(iso(15000));r["expiresAt"]=json!(iso(45000));
  if case!="all_old"{for ex in ["101","102"]{let mut b=book(ex);b["receivedAt"]=json!(iso(15000));for k in ["receivedAt","sourceAt","requestStartedAt"]{b["book"][k]=json!(iso(15000));}b["book"][if case=="source_old"{"sourceAt"}else{"requestStartedAt"}]=json!(iso(0));b["book"]["sequence"]=json!("2");r["legs"][if ex=="101"{0}else{1}]["bookHash"]=json!(hash(&b["book"]));e.advance(&b).unwrap();}}
  deny(&mut e,&r);assert_eq!(e.report().unwrap()["reservedCash"],"0.000000");
 }
}
#[test]fn package_expiry_still_obeys_lifetime_entry_cutoff_and_original_attempt_deadline(){
 for case in ["lifetime","entry"]{let mut p=policy();p["lifetimeMs"]=json!(30000);let mut e=engine_with(&p);let mut r=reserve(2);r["expiresAt"]=json!(if case=="lifetime"{iso(30002)}else{iso(100001)});deny(&mut e,&r);}
 let mut e=engine();let mut r=reserve(2);r["expiresAt"]=json!(iso(30001));e.advance(&r).unwrap();
 let mut a=event("live_package_attempt",30001);a["expiresAt"]=json!(iso(60000));deny(&mut e,&a);assert_eq!(e.package_records()[0]["phase"],"reserved");assert_eq!(e.package_records()[0]["expiresAt"],1_792_022_430_001i64);
}
